#!/usr/bin/env python3
"""RISK1 analysis (registration planned/RISK1_PREREG.md). Run from the repo root after planned/risk1_run.js.
Reads out/risk1/*.jsonl (planned cross-company encounters with their CPA), computes expected collisions with the Reich-type
formula of lab/risk.js for each error case and aircraft size, prints the verdict on each prediction, writes planned/risk1_results_table.md."""
import glob, json, math, random
R = [json.loads(l) for f in sorted(glob.glob('out/risk1/*.jsonl')) for l in open(f) if l.strip()]
METROS = ('houston', 'dfw'); ARMS = ('S1', 'A2'); K_RAD = math.sqrt(-2 * math.log(0.05)); K_VER = 1.96
LV = {'L0': (0, 0), 'L1': (3, 4), 'L2': (8, 13), 'L4': (30.48, 45.72)}     # 95 % sideways, 95 % height (m), as ERRORS1
CASES = [('L0', 'L0', 0), ('L1', 'L1', 0), ('L2', 'L2', 0), ('L2 shared 0.8', 'L2', 0.8), ('L2 shared 0.95', 'L2', 0.95), ('L4 (lower bound)', 'L4', 0)]
WING = (0.65, 0.25)                                    # half-length 1.3 m / 2 (Smithsonian: length ~1.3 m, span ~1.0 m); half-height assumed
BIG = {'small': 1.0, 'base': 1.5, 'large': 2.0}        # Zipline P2 and Amazon MK30 half-span (m): not published, assumed
BIG_H = 0.3                                            # half-height, assumed
Phi = lambda x: 0.5 * (1 + math.erf(x / math.sqrt(2)))
def band(d, W, s): return Phi((W - d) / s) - Phi((-W - d) / s) if s > 0 else (1.0 if abs(d) < W else 0.0)
def size(op, big): return WING if op == 'wing' else (BIG[big], BIG_H)
def expected(row, lv, rho, big):
    h95, v95 = LV[lv]; f = math.sqrt(1 - rho); sh = math.sqrt(2) * f * h95 / K_RAD; sz = math.sqrt(2) * f * v95 / K_VER; p = 0.0
    for opA, opB, dperp, dz, dh, vrel in row['enc']:
        A, B = size(opA, big), size(opB, big); p += band(dperp, A[0] + B[0], sh) * band(dz, A[1] + B[1], sz)
    return p
def rows(m, arm): return {r['seed']: r for r in R if r['metro'] == m and r['arm'] == arm}
def rate(m, arm, lv, rho, big, seeds=None):   # expected collisions per 100,000 flight hours, pooled over seeds
    x = rows(m, arm); ss = sorted(seeds if seeds else x); return 1e5 * sum(expected(x[s], lv, rho, big) for s in ss) / sum(x[s]['flightHours'] for s in ss)
def cut(m, lv, rho, big, ci=False):
    ss = sorted(set(rows(m, 'S1')) & set(rows(m, 'A2')))
    pre = {a: {s: (expected(rows(m, a)[s], lv, rho, big), rows(m, a)[s]['flightHours']) for s in ss} for a in ARMS}
    f = lambda S: 1 - (sum(pre['A2'][s][0] for s in S) / sum(pre['A2'][s][1] for s in S)) / (sum(pre['S1'][s][0] for s in S) / sum(pre['S1'][s][1] for s in S)) if sum(pre['S1'][s][0] for s in S) > 0 else float('nan')
    if not ci: return f(ss)
    g = random.Random(1); bs = sorted(v for v in (f([g.choice(ss) for _ in ss]) for _ in range(2000)) if v == v); return f(ss), bs[int(0.025 * len(bs))], bs[int(0.975 * len(bs)) - 1]
P = []
def chk(name, ok, text): P.append((name, ok, text)); print('PASS' if ok else 'FAIL', name, text)
c1 = {m: cut(m, 'L1', 0, 'base') for m in METROS}
chk('R1', all(0.40 <= c1[m] <= 0.90 for m in METROS), 'collision-risk cut by height sharing at L1, base sizes: ' + ', '.join(f'{m} {100 * c1[m]:.0f} %' for m in METROS))
r2 = {(m, a): (rate(m, a, 'L0', 0, 'base'), rate(m, a, 'L2', 0, 'base')) for m in METROS for a in ARMS}
chk('R2', all(r2[k][1] >= r2[k][0] for k in r2), 'risk per 100,000 flight hours, L0 vs L2: ' + '; '.join(f'{m} {a} {r2[(m, a)][0]:.3g} vs {r2[(m, a)][1]:.3g}' for m, a in r2))
r3 = {(m, a): (rate(m, a, 'L2', 0.95, 'base'), rate(m, a, 'L2', 0, 'base')) for m in METROS for a in ARMS}
chk('R3', all(r3[k][0] < r3[k][1] for k in r3), 'L2 with 95 % shared vs independent: ' + '; '.join(f'{m} {a} {r3[(m, a)][0]:.3g} vs {r3[(m, a)][1]:.3g}' for m, a in r3))
r4 = {(m, a): rate(m, a, 'L2', 0, 'large') / rate(m, a, 'L2', 0, 'small') for m in METROS for a in ARMS}
chk('R4', all(1.4 <= v <= 2.5 for v in r4.values()), 'risk ratio, Zipline/Amazon half-span 2.0 m vs 1.0 m (L2): ' + '; '.join(f'{m} {a} {v:.2f}' for (m, a), v in r4.items()))
r5 = {m: (rate(m, 'A2', 'L2', 0, 'base'), rate(m, 'S1', 'L2', 0, 'base')) for m in METROS}
chk('R5', all(r5[m][0] < r5[m][1] for m in METROS), 'L2 risk, shared-out vs best-sourced heights: ' + '; '.join(f'{m} {r5[m][0]:.3g} vs {r5[m][1]:.3g}' for m in METROS))
npass = sum(1 for _, ok, _ in P if ok)
T = ['# RISK1 results table (generated by planned/risk1_analyze.py)', '', f'{npass} of {len(P)} predictions passed. Rows: {len(R)} (city x arm x seed); encounters with a CPA: {sum(len(r["enc"]) for r in R)}; without: {sum(r["noCPA"] for r in R)}.', '']
T += [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
T += ['', '## Expected collisions per 100,000 flight hours (all airborne hours in the measured window), base sizes', '', '| Metro | Case | Best-sourced heights (S1) | Shared-out heights (A2) | Cut [95 % over seeds] |', '|---|---|---|---|---|']
for m in METROS:
    for name, lv, rho in CASES:
        f, lo, hi = cut(m, lv, rho, 'base', True); T.append(f'| {m} | {name} | {rate(m, "S1", lv, rho, "base"):.3g} | {rate(m, "A2", lv, rho, "base"):.3g} | {100 * f:.0f} % [{100 * lo:.0f}-{100 * hi:.0f}] |')
T += ['', '## Sensitivity to the assumed size of Zipline and Amazon aircraft (L2, independent errors)', '', '| Metro | Arm | half-span 1.0 m | 1.5 m | 2.0 m |', '|---|---|---|---|---|']
for m in METROS:
    for a in ARMS: T.append(f'| {m} | {a} | ' + ' | '.join(f'{rate(m, a, "L2", 0, b):.3g}' for b in ('small', 'base', 'large')) + ' |')
T += ['', '## Encounters and flight hours (pooled over seeds)', '', '| Metro | Arm | Seeds | Encounters | Flight hours | Encounters per flight hour |', '|---|---|---|---|---|---|']
for m in METROS:
    for a in ARMS:
        x = rows(m, a); n = sum(len(r['enc']) for r in x.values()); h = sum(r['flightHours'] for r in x.values()); T.append(f'| {m} | {a} | {len(x)} | {n} | {h:.0f} | {n / h:.2f} |')
open('planned/risk1_results_table.md', 'w').write('\n'.join(T) + '\n'); print(f'{npass} of {len(P)} passed')
